import { Auth0Provider, useAuth0 } from '@auth0/auth0-react';

function App() {
  return (
    <Auth0Provider
      domain={process.env.REACT_APP_AUTH0_DOMAIN}
      clientId={process.env.REACT_APP_AUTH0_CLIENT_ID}
      redirectUri={window.location.origin}
      onRedirectCallback={handleRedirectCallback}
    >
      <MainApp />
    </Auth0Provider>
  );
}

function handleRedirectCallback({ appState }) {
  // This is called after the redirect from Auth0
  console.log('Redirect callback called', appState);

  // You can check if the user is authenticated here
  const { isAuthenticated } = useAuth0();
  if (isAuthenticated) {
    // Perform your logic, like checking if a service is running
    checkKnativeService();
  }
}

function MainApp() {
  const { isAuthenticated } = useAuth0();

  if (!isAuthenticated) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h1>Welcome, user!</h1>
      {/* Your app content */}
    </div>
  );
}
```

---

