function App() {
  return (
    <Auth0Provider
      domain={process.env.REACT_APP_AUTH0_DOMAIN}
      clientId={process.env.REACT_APP_AUTH0_CLIENT_ID}
      onLogin={handleLogin}
    >
      <MainApp />
    </Auth0Provider>
  );
}

function handleLogin(user) {
  console.log('User logged in:', user);
  checkKnativeService();
